/**
 * Split text into sentences. Returns the sentences joined by '\n'.
 */
export function textToSentences(text: string): string;

/**
 * Split text into words. Returns the words joined by ' '.
 */
export function textToWords(text: string): string;

/**
 * Tokenization result with source spans.
 *
 * `spans` hold per-token `[start, end]` offsets into the ORIGINAL input
 * string, in UTF-16 code units with `end` exclusive — i.e. directly
 * usable as `text.slice(start, end)`.
 */
export interface TokenizeResult {
  /** '\n'-separated sentences or ' '-separated words. */
  text: string;
  spans: Array<[number, number]>;
}

export function textToSentencesWithOffsets(text: string): TokenizeResult;
export function textToWordsWithOffsets(text: string): TokenizeResult;
